"""Tests of the robot description generated by xacro."""

import math
import struct
import xml.etree.ElementTree as ET
from pathlib import Path
from xml.dom.minidom import Node

import pytest
import xacro

URDF = Path(__file__).resolve().parents[1] / "urdf" / "minipock.urdf.xacro"
NAMESPACE = "minipock_0"
MODES = ("differential", "holonomic")
WHEEL_SEPARATION = 0.328
WHEEL_RADIUS = 0.0355
MODELS = URDF.parents[1] / "models"
LIDAR_LINK = f"{NAMESPACE}/lidar_link"

# Gazebo visibility bits (gz-rendering 8): GZ_VISIBILITY_ALL is 0x0FFFFFFF (GUI cameras), bits 0
# and 1 are GZ_VISIBILITY_GUI and GZ_VISIBILITY_SELECTABLE, bit 20 is reserved for particles.
GZ_VISIBILITY_ALL = 0x0FFFFFFF
GZ_RESERVED_BITS = 0x00000001 | 0x00000002 | 0x00100000
MAX_ROBOTS = 18

# Axis-aligned bounds of the visual meshes, in their own frame, as [[min xyz], [max xyz]] (m).
# Measured with trimesh (`uv run --with trimesh --with pycollada ...`); the STL ones are checked
# against the files by `test_stl_bounds_match_files`.
MESH_BOUNDS = {
    "base_alu.dae": ((-0.15, -0.171, -0.089), (0.15, 0.171, 0.0)),
    "base_pla.stl": ((-0.15, -0.171, -0.096), (0.15, 0.171, -0.006)),
    "base_pmma.stl": ((-0.15, -0.1692, -0.0857), (0.15, 0.1692, -0.0063)),
    "misc.stl": ((-0.1461, -0.0972, -0.086), (0.146, 0.1443, 0.043)),
    "lds_visual.dae": ((-0.033, -0.0191, -0.0345), (0.062, 0.0201, 0.0345)),
    "wheel_base.dae": ((-0.0375, 0.0, -0.017), (0.0375, 0.055, 0.1046)),
    "wheel_rotative.dae": ((-0.0359, -0.0119, -0.0375), (0.0359, 0.0599, 0.0031)),
    "wheel_core.stl": ((-0.0339, 0.0, -0.0326), (0.0339, 0.005, 0.0344)),
    "roller.stl": ((-0.0061, -0.0061, -0.008), (0.0061, 0.0061, 0.008)),
}


def _convert(node: Node) -> ET.Element:
    """Convert a minidom element, as returned by xacro, into an ElementTree element."""
    element = ET.Element(node.tagName, dict(node.attributes.items()))
    text = "".join(c.data for c in node.childNodes if c.nodeType == Node.TEXT_NODE).strip()
    element.text = text or None
    for child in node.childNodes:
        if child.nodeType == Node.ELEMENT_NODE:
            element.append(_convert(child))
    return element


def _robot(mode: str, **mappings: str) -> ET.Element:
    """Process the source file with xacro and return the resulting URDF."""
    document = xacro.process_file(
        str(URDF), mappings={"namespace": f"{NAMESPACE}/", "mode": mode, **mappings}
    )
    return _convert(document.documentElement)


def _xyz_rpy(element: ET.Element | None) -> tuple[list[float], list[float]]:
    """Return the xyz and rpy of an `origin` element (zeros when absent)."""
    if element is None:
        return [0.0] * 3, [0.0] * 3
    xyz = [float(v) for v in element.get("xyz", "0 0 0").split()]
    rpy = [float(v) for v in element.get("rpy", "0 0 0").split()]
    return xyz, rpy


def _yaw_rotate(vec: list[float], yaw: float) -> list[float]:
    """Rotate a vector around z."""
    cos, sin = math.cos(yaw), math.sin(yaw)
    return [cos * vec[0] - sin * vec[1], sin * vec[0] + cos * vec[1], vec[2]]


def _wheel_contact_y(robot: ET.Element, side: str) -> float:
    """Return the y position, in the base frame, of the wheel contact axis.

    Composes the motor joint origin, the wheel joint origin and the origin of the
    wheel collision cylinder. Only yaw rotations are used by the motor joints.
    """
    motor_joint = robot.find(f"joint[@name='{NAMESPACE}/motor_{side}_joint']")
    wheel_joint = robot.find(f"joint[@name='{NAMESPACE}/motor_{side}_wheel_joint']")
    wheel_link = robot.find(f"link[@name='{NAMESPACE}/motor_{side}_wheel_link']")
    assert motor_joint is not None
    assert wheel_joint is not None
    assert wheel_link is not None
    motor_xyz, motor_rpy = _xyz_rpy(motor_joint.find("origin"))
    wheel_xyz, _ = _xyz_rpy(wheel_joint.find("origin"))
    collision_xyz, _ = _xyz_rpy(wheel_link.find("collision/origin"))
    local = [a + b for a, b in zip(wheel_xyz, collision_xyz, strict=True)]
    rotated = _yaw_rotate(local, motor_rpy[2])
    return motor_xyz[1] + rotated[1]


@pytest.fixture(params=MODES)
def robot(request: pytest.FixtureRequest) -> ET.Element:
    """Parsed robot for each mode."""
    return _robot(request.param)


@pytest.fixture(scope="module")
def differential() -> ET.Element:
    """Parsed robot in differential mode."""
    return _robot("differential")


def test_links_prefixed(robot: ET.Element) -> None:
    names = [link.get("name") for link in robot.findall("link")]
    assert names
    assert all(name.startswith(f"{NAMESPACE}/") for name in names)


def test_lidar_joint_fixed(robot: ET.Element) -> None:
    joint = robot.find("joint[@name='lidar_joint']")
    assert joint is not None
    assert joint.get("type") == "fixed"
    assert joint.find("limit") is None
    assert joint.find("axis") is None


def test_lidar_matches_firmware(robot: ET.Element) -> None:
    sensor = robot.find(".//sensor[@type='gpu_lidar']")
    assert sensor is not None
    assert int(sensor.findtext("lidar/scan/horizontal/samples")) == 132
    assert float(sensor.findtext("lidar/range/min")) == pytest.approx(0.02)
    assert float(sensor.findtext("lidar/range/max")) == pytest.approx(12.0)
    assert float(sensor.findtext("update_rate")) == pytest.approx(10)
    noise = sensor.find("lidar/noise")
    assert noise is not None
    assert noise.findtext("type") == "gaussian"
    assert float(noise.findtext("stddev")) == pytest.approx(0.01)


def test_lidar_frame_id(robot: ET.Element) -> None:
    sensor = robot.find(".//sensor[@type='gpu_lidar']")
    assert sensor is not None
    assert sensor.findtext("gz_frame_id") == f"{NAMESPACE}/lidar_link"
    assert sensor.findtext("topic") == f"{NAMESPACE}/scan"


def test_diff_drive_matches_firmware(differential: ET.Element) -> None:
    plugin = differential.find(".//plugin[@name='gz::sim::systems::DiffDrive']")
    assert plugin is not None
    assert float(plugin.findtext("wheel_separation")) == pytest.approx(WHEEL_SEPARATION)
    assert float(plugin.findtext("wheel_radius")) == pytest.approx(WHEEL_RADIUS)
    distance = abs(
        _wheel_contact_y(differential, "left") - _wheel_contact_y(differential, "right")
    )
    assert distance == pytest.approx(WHEEL_SEPARATION, abs=1e-3)
    for side in ("left", "right"):
        radius = differential.find(
            f"link[@name='{NAMESPACE}/motor_{side}_wheel_link']/collision/geometry/cylinder"
        )
        assert radius is not None
        assert float(radius.get("radius")) == pytest.approx(WHEEL_RADIUS)


@pytest.fixture(scope="module")
def holonomic() -> ET.Element:
    """Parsed robot in holonomic mode."""
    return _robot("holonomic")


def test_holonomic_has_no_roller_joints(holonomic: ET.Element) -> None:
    joints = holonomic.findall("joint")
    assert not [j.get("name") for j in joints if "roller" in j.get("name")]
    links = holonomic.findall("link")
    assert not [link.get("name") for link in links if "roller" in link.get("name")]
    continuous = [j.get("name") for j in joints if j.get("type") == "continuous"]
    assert sorted(continuous) == sorted(
        f"{NAMESPACE}/motor_{m}_wheel_joint" for m in ("left", "right", "middle")
    )


def test_holonomic_keeps_roller_visuals(holonomic: ET.Element) -> None:
    for motor in ("left", "right", "middle"):
        link = holonomic.find(f"link[@name='{NAMESPACE}/motor_{motor}_wheel_link']")
        assert link is not None
        visuals = link.findall("visual")
        assert len(visuals) == 1 + 9
        meshes = [v.find("geometry/mesh").get("filename") for v in visuals]
        assert sum(m.endswith("roller.stl") for m in meshes) == 9


def test_holonomic_wheel_collision(holonomic: ET.Element) -> None:
    for motor in ("left", "right", "middle"):
        link = holonomic.find(f"link[@name='{NAMESPACE}/motor_{motor}_wheel_link']")
        assert link is not None
        collisions = link.findall("collision")
        assert len(collisions) == 1
        cylinder = collisions[0].find("geometry/cylinder")
        assert cylinder is not None
        assert float(cylinder.get("radius")) == pytest.approx(WHEEL_RADIUS)


def _lidar_flags_and_mask(robot: ET.Element) -> tuple[int, int]:
    """Return the visibility flags of the LiDAR visual and the visibility mask of the LiDAR."""
    gazebo = robot.find(f"gazebo[@reference='{LIDAR_LINK}']")
    assert gazebo is not None
    flags = gazebo.findtext("visual/visibility_flags")
    mask = gazebo.findtext("sensor[@type='gpu_lidar']/lidar/visibility_mask")
    assert flags is not None
    assert mask is not None
    return int(flags), int(mask)


def test_lidar_visual_hidden_from_own_lidar(robot: ET.Element) -> None:
    # The sensor origin is inside the LD19 mesh: gpu_lidar would hit it at the minimum range.
    flags, mask = _lidar_flags_and_mask(robot)
    assert flags != 0
    assert flags & mask == 0


def test_lidar_visual_merged_by_sdformat(robot: ET.Element) -> None:
    # sdformat applies a `<gazebo reference><visual>` block only to the visual it names
    # `<link>_visual`, that is a URDF visual without a name.
    link = robot.find(f"link[@name='{LIDAR_LINK}']")
    assert link is not None
    visuals = link.findall("visual")
    assert len(visuals) == 1
    assert visuals[0].get("name") is None


@pytest.mark.parametrize("index", [0, 1, MAX_ROBOTS - 1])
def test_lidar_visual_seen_by_gui_cameras(index: int) -> None:
    flags, mask = _lidar_flags_and_mask(_robot("differential", sim_index=str(index)))
    assert flags & GZ_VISIBILITY_ALL == flags
    assert flags & GZ_RESERVED_BITS == 0
    assert mask | flags == 0xFFFFFFFF


def test_robots_see_each_other_lidar() -> None:
    indices = (0, 1, MAX_ROBOTS - 1)
    robots = {i: _lidar_flags_and_mask(_robot("holonomic", sim_index=str(i))) for i in indices}
    for i in indices:
        for j in indices:
            if i != j:
                assert robots[i][1] & robots[j][0] != 0


def test_lidar_bits_distinct_and_masks_exclude_only_own_bit() -> None:
    lidars = [
        _lidar_flags_and_mask(_robot("differential", sim_index=str(i))) for i in range(MAX_ROBOTS)
    ]
    flags = [flag for flag, _ in lidars]
    assert len(set(flags)) == MAX_ROBOTS
    for own, (flag, mask) in enumerate(lidars):
        assert flag & mask == 0
        for other, (other_flag, _) in enumerate(lidars):
            if other != own:
                assert mask & other_flag == other_flag


@pytest.mark.parametrize("index", ["-1", str(MAX_ROBOTS)])
def test_sim_index_out_of_range_rejected(index: str) -> None:
    with pytest.raises(xacro.XacroException):
        _robot("differential", sim_index=index)


def _rpy_matrix(rpy: list[float]) -> list[list[float]]:
    """Return the URDF rotation matrix Rz(yaw) Ry(pitch) Rx(roll)."""
    cr, sr = math.cos(rpy[0]), math.sin(rpy[0])
    cp, sp = math.cos(rpy[1]), math.sin(rpy[1])
    cy, sy = math.cos(rpy[2]), math.sin(rpy[2])
    return [
        [cy * cp, cy * sp * sr - sy * cr, cy * sp * cr + sy * sr],
        [sy * cp, sy * sp * sr + cy * cr, sy * sp * cr - cy * sr],
        [-sp, cp * sr, cp * cr],
    ]


def _compose(
    outer: tuple[list[list[float]], list[float]], inner: tuple[list[list[float]], list[float]]
) -> tuple[list[list[float]], list[float]]:
    """Compose two rigid transforms given as (rotation, translation)."""
    rot_o, pos_o = outer
    rot_i, pos_i = inner
    rot = [[sum(rot_o[r][k] * rot_i[k][c] for k in range(3)) for c in range(3)] for r in range(3)]
    pos = [sum(rot_o[r][k] * pos_i[k] for k in range(3)) + pos_o[r] for r in range(3)]
    return rot, pos


def _origin(element: ET.Element | None) -> tuple[list[list[float]], list[float]]:
    """Return the transform of an `origin` element."""
    xyz, rpy = _xyz_rpy(element)
    return _rpy_matrix(rpy), xyz


def _link_in_base(robot: ET.Element, link: str) -> tuple[list[list[float]], list[float]]:
    """Return the transform of a link in base_link, through fixed and zero-position joints."""
    parents = {
        j.find("child").get("link"): (j.find("parent").get("link"), _origin(j.find("origin")))
        for j in robot.findall("joint")
    }
    transform = _origin(None)
    while link != f"{NAMESPACE}/base_link":
        link, joint = parents[link]
        transform = _compose(joint, transform)
    return transform


def _visual_z_range(
    robot: ET.Element, link: ET.Element, visual: ET.Element
) -> tuple[float, float]:
    """Return the z range in base_link of the bounding box of a mesh visual."""
    mesh = visual.find("geometry/mesh")
    lower, upper = MESH_BOUNDS[mesh.get("filename").rsplit("/", 1)[-1]]
    rot, pos = _compose(_link_in_base(robot, link.get("name")), _origin(visual.find("origin")))
    corners = [
        (x, y, z)
        for x in (lower[0], upper[0])
        for y in (lower[1], upper[1])
        for z in (lower[2], upper[2])
    ]
    heights = [sum(rot[2][k] * c[k] for k in range(3)) + pos[2] for c in corners]
    return min(heights), max(heights)


def test_scan_plane_clear_of_robot_body(robot: ET.Element) -> None:
    # Only the LiDAR itself crosses its scan plane: no pillar or body part is in view, so the
    # real robot needs no footprint filter and the simulation only hides the LD19 mesh.
    _, lidar_pos = _link_in_base(robot, LIDAR_LINK)
    plane = lidar_pos[2]
    crossing = []
    for link in robot.findall("link"):
        for visual in link.findall("visual"):
            low, high = _visual_z_range(robot, link, visual)
            if low <= plane <= high:
                crossing.append(link.get("name"))
    assert crossing == [LIDAR_LINK]


def _stl_bounds(path: Path) -> tuple[tuple[float, ...], tuple[float, ...]]:
    """Return the bounds of a binary STL file."""
    data = path.read_bytes()
    (count,) = struct.unpack_from("<I", data, 80)
    lower, upper = [math.inf] * 3, [-math.inf] * 3
    for triangle in range(count):
        values = struct.unpack_from("<9f", data, 84 + 50 * triangle + 12)
        for vertex in range(3):
            for axis in range(3):
                value = values[3 * vertex + axis]
                lower[axis] = min(lower[axis], value)
                upper[axis] = max(upper[axis], value)
    return tuple(lower), tuple(upper)


@pytest.mark.parametrize("name", [n for n in MESH_BOUNDS if n.endswith(".stl")])
def test_stl_bounds_match_files(name: str) -> None:
    lower, upper = _stl_bounds(MODELS / name)
    assert lower == pytest.approx(MESH_BOUNDS[name][0], abs=1e-4)
    assert upper == pytest.approx(MESH_BOUNDS[name][1], abs=1e-4)
